try{require_disposable_test_profile();}catch(Throwable $e){fwrite(STDERR,"REFUSED: ".$e->getMessage()."\n");exit(2);}
$base=rtrim($argv[1]??'','/');if($base===''||!in_array(strtolower((string)parse_url($base,PHP_URL_HOST)),['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: position-error tests require loopback API.\n");exit(2);}
