function position_assert(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);echo "PASS $message\n";}
function position_call(string $method,string $path,?array $payload=null):array{$headers="Content-Type: application/json\r\nCookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n";$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$payload===null?'':json_encode($payload,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>8]]);$raw=@file_get_contents($GLOBALS['base'].$path,false,$ctx);$status=(int)substr($http_response_header[0]??'HTTP/1.1 500',9,3);return['status'=>$status,'raw'=>is_string($raw)?$raw:'','body'=>is_string($raw)?json_decode($raw,true):null];}
function position_expect(int $status,array $result,string $what):array{if($result['status']!==$status)throw new RuntimeException("$what expected HTTP $status, got {$result['status']}: {$result['raw']}");echo "PASS $what returns HTTP $status\n";return is_array($result['body'])?$result['body']:[];}
function position_session(PDO $pdo,string $phase='PHASE2'):int{$q=$pdo->prepare('INSERT INTO test_sessions(site_id,label,phase,design,tester_code,test_point) VALUES(?,?,?,?,?,?)');$q->execute(['pup','P8 position scratch '.$phase.' '.bin2hex(random_bytes(3)),$phase,'A','P8','scratch']);return(int)$pdo->lastInsertId();}
function position_packet(PDO $pdo,int $hiker,int $session,float $lat,float $lon,string $receivedAt):void{$q=$pdo->prepare("INSERT INTO uplink_packets(hiker_node_id,site_id,sequence_number,latitude,longitude,gps_accuracy_m,satellite_count,battery_level,classification,session_id,received_at,is_duplicate,test_mode,is_demo) VALUES(:hiker,'pup',:sequence,:lat,:lon,5,7,80,'INSIDE',:session,:received,0,1,1)");$q->execute(['hiker'=>$hiker,'sequence'=>random_int(100000,2000000000),'lat'=>$lat,'lon'=>$lon,'session'=>$session,'received'=>$receivedAt]);}
function stamp_pair(int $insideOffset,int $outsideOffset):array{$now=new DateTimeImmutable('now',new DateTimeZone('UTC'));return[$now->modify('-'.$insideOffset.' seconds')->format('Y-m-d H:i:s'),$now->modify('-'.$outsideOffset.' seconds')->format('Y-m-d H:i:s')];}
function record_pair(PDO $pdo,string $base,int $hiker,int $session,int $gate,float $tape,int $insideOffset,int $outsideOffset):array{[$insideEnd,$outsideEnd]=stamp_pair($insideOffset,$outsideOffset);$insideAt=(new DateTimeImmutable($insideEnd,new DateTimeZone('UTC')))->modify('-5 seconds')->format('Y-m-d H:i:s');$outsideAt=(new DateTimeImmutable($outsideEnd,new DateTimeZone('UTC')))->modify('-5 seconds')->format('Y-m-d H:i:s');position_packet($pdo,$hiker,$session,14.0,121.0,$insideAt);position_packet($pdo,$hiker,$session,14.0001,121.0,$outsideAt);return position_expect(201,position_call('POST','/api/position-errors',['session_id'=>$session,'node_id'=>'H1','gate_no'=>$gate,'tape_distance_m'=>$tape,'inside_end_utc'=>$insideEnd,'outside_end_utc'=>$outsideEnd]),'position error measurement');}
try{
 $pdo=db();position_expect(200,position_call('POST','/api/settings/site',['site_id'=>'pup']),'select PUP site');$h=$pdo->prepare('SELECT id FROM hiker_nodes WHERE node_id=?');$h->execute(['H1']);$hiker=(int)$h->fetchColumn();if(!$hiker)throw new RuntimeException('Seeded scratch hiker H1 was not found.');
 position_assert(abs(haversine_distance_m(0,0,0.0001,0)-11.12)<0.05,'haversine returns about 11.12 m for 0.0001 degree of latitude');
 $session=position_session($pdo);$positive=record_pair($pdo,$base,$hiker,$session,1,10.0,60,40);$negative=record_pair($pdo,$base,$hiker,$session,2,12.0,30,10);position_assert((float)$positive['check']['error_m']>0&&(float)$negative['check']['error_m']<0,'position error is signed positive and negative relative to tape distance');
 $summary=position_expect(200,position_call('GET','/api/position-errors?session_id='.$session),'position error session list');position_assert($summary['summary']['count']===2&&abs($summary['summary']['mean_signed_error_m']-0.12)<0.01&&abs($summary['summary']['mean_absolute_error_m']-1.0)<0.01&&abs($summary['summary']['largest_absolute_error_m']-1.12)<0.01,'position error summary reports count, signed mean, absolute mean, and largest absolute error');
 $csvSession=position_session($pdo);record_pair($pdo,$base,$hiker,$csvSession,3,10.0,60,40);$csv=position_call('GET','/api/export.csv?type=position_errors&session_id='.$csvSession);if($csv['status']!==200)throw new RuntimeException('position error CSV export expected HTTP 200, got '.$csv['status'].': '.$csv['raw']);echo "PASS position error CSV export returns HTTP 200\n";$lines=array_values(array_filter(preg_split('/\r?\n/',$csv['raw']),static fn($line)=>$line!==''));$header=str_getcsv($lines[0]??'');$expected=['created_at','node_id','gate_no','window_seconds','inside_window_start','inside_window_end','inside_valid_fix_count','inside_mean_latitude','inside_mean_longitude','outside_window_start','outside_window_end','outside_valid_fix_count','outside_mean_latitude','outside_mean_longitude','tape_distance_m','phone_distance_m','error_m'];position_assert($header===$expected&&count($lines)===2&&count(str_getcsv($lines[1]??''))===count($expected),'position error CSV has the specified header order and one data row');
 $zeroSession=position_session($pdo);[$insideEnd,$outsideEnd]=stamp_pair(30,10);$before=(int)$pdo->query('SELECT COUNT(*) FROM position_error_checks')->fetchColumn();$zero=position_expect(422,position_call('POST','/api/position-errors',['session_id'=>$zeroSession,'node_id'=>'H1','gate_no'=>1,'tape_distance_m'=>10,'inside_end_utc'=>$insideEnd,'outside_end_utc'=>$outsideEnd]),'zero-fix position error');$after=(int)$pdo->query('SELECT COUNT(*) FROM position_error_checks')->fetchColumn();position_assert(str_contains($zero['error']??'','Both 10-second windows')&&$after===$before,'zero valid fixes return HTTP 422 without saving');
 $phase3=position_session($pdo,'PHASE3');[$insideEnd,$outsideEnd]=stamp_pair(30,10);position_expect(409,position_call('POST','/api/position-errors',['session_id'=>$phase3,'node_id'=>'H1','gate_no'=>1,'tape_distance_m'=>10,'inside_end_utc'=>$insideEnd,'outside_end_utc'=>$outsideEnd]),'non-PHASE2 position error is rejected clearly');
}catch(Throwable $e){fwrite(STDERR,'FAIL '.$e->getMessage()."\n");exit(1);}
